function sceneOffset(scene){return S.project.scenes.slice(0,S.project.scenes.indexOf(scene)).reduce((sum,item)=>sum+item.duration,0)}
function visibleDuration(layer,scene){return layer.duration||scene.duration-layer.start}
function snapTime(value,candidates,pixelsPerSecond){const frame=1/S.project.fps,framed=Math.round(value/frame)*frame;if(!S.snap)return{value:framed};const threshold=Math.max(frame,8/pixelsPerSecond);let best=framed,guide;for(const candidate of candidates){if(Math.abs(candidate-value)<=threshold&&Math.abs(candidate-value)<Math.abs(best-value)+.000001){best=candidate;guide=candidate}}return{value:best,guide}}
function snapRange(start,length,candidates,pixelsPerSecond){const atStart=snapTime(start,candidates,pixelsPerSecond),atEnd=snapTime(start+length,candidates,pixelsPerSecond);return Math.abs(atEnd.value-(start+length))<Math.abs(atStart.value-start)?{value:atEnd.value-length,guide:atEnd.guide}:atStart}
function showTimelineGuide(time){const guide=$('#timelineGuide');if(!guide)return;if(time===undefined){guide.style.display='none';return}guide.style.display='block';guide.style.left=time/duration()*100+'%'}
function timelineCandidates(scene,excludeLayer){const values=[0,scene.duration,S.frame/S.project.fps-sceneOffset(scene)];scene.layers.forEach(layer=>{if(layer===excludeLayer)return;values.push(layer.start,layer.start+visibleDuration(layer,scene))});return values.filter(value=>value>=0&&value<=scene.duration)}
function renderTimeline(){const total=duration(),width=Math.max(900,total*110*S.timelineZoom);$('#tracks').style.width=width+'px';let cursor=0,sceneClips='',tracks='',labels='<div class="track-label-row"><strong>Scenes</strong></div>';const offsets={};S.project.scenes.forEach(scene=>{offsets[scene.id]=cursor;const left=cursor/total*100,w=scene.duration/total*100;sceneClips+='<div class="clip scene-strip '+(S.selected.kind==='scene'&&S.selected.id===scene.id?'active':'')+'" data-sceneclip="'+esc(scene.id)+'" style="left:'+left+'%;width:'+w+'%">'+esc(scene.id)+' · '+scene.duration.toFixed(2)+'s</div>';cursor+=scene.duration});tracks='<div class="track">'+sceneClips+'</div>';S.project.scenes.forEach(scene=>scene.layers.forEach(layer=>{const layerDuration=visibleDuration(layer,scene),left=(offsets[scene.id]+layer.start)/total*100,w=layerDuration/total*100;labels+='<div class="track-label-row"><span class="tree-icon">'+icon(layer.type)+'</span><strong>'+esc(layer.id)+'</strong></div>';tracks+='<div class="track"><div class="clip layer-strip '+(S.selected.kind==='layer'&&S.selected.id===layer.id?'active':'')+'" role="button" tabindex="0" aria-label="'+esc(layer.id)+' clip" data-layerclip="'+esc(layer.id)+'" data-scene="'+esc(scene.id)+'" style="left:'+left+'%;width:'+w+'%"><span class="clip-handle left" data-layer-handle="left"></span>'+esc(layer.id)+'<span class="clip-handle right" data-layer-handle="right"></span></div></div>';layer.motion.forEach((motion,index)=>{const phaseLeft=(offsets[scene.id]+layer.start+motion.start)/total*100,phaseWidth=motion.duration/total*100,active=S.selected.kind==='motion'&&S.selected.sceneId===scene.id&&S.selected.layerId===layer.id&&S.selected.motionIndex===index;labels+='<div class="track-label-row phase-label"><span class="tree-icon">↗</span><strong>'+esc(motion.recipe)+'</strong></div>';tracks+='<div class="track phase-track"><div class="phase-clip '+(active?'active':'')+'" role="button" tabindex="0" aria-label="'+esc(motion.recipe)+' motion phase" data-phase="'+index+'" data-scene="'+esc(scene.id)+'" data-layer="'+esc(layer.id)+'" style="left:'+phaseLeft+'%;width:'+phaseWidth+'%"><span class="phase-handle left" data-phase-handle="left"></span>'+esc(motion.recipe)+'<span class="phase-handle right" data-phase-handle="right"></span></div></div>'})}));S.project.audio.forEach(track=>{const length=track.duration||Math.max(1/S.project.fps,total-track.start),left=track.start/total*100,w=length/total*100;labels+='<div class="track-label-row"><span class="tree-icon">♪</span><strong>'+esc(track.id)+'</strong></div>';tracks+='<div class="track"><div class="clip audio-strip '+(S.selected.kind==='audio'&&S.selected.id===track.id?'active':'')+'" role="button" tabindex="0" aria-label="'+esc(track.id)+' audio clip" data-audioclip="'+esc(track.id)+'" style="left:'+left+'%;width:'+w+'%"><span class="clip-handle left" data-audio-handle="left"></span>'+esc(track.id)+'<span class="clip-handle right" data-audio-handle="right"></span></div></div>'});$('#tracks').innerHTML=tracks+'<div class="timeline-guide" id="timelineGuide"></div><div class="playhead" id="playhead"></div>';$('#trackLabels').innerHTML=labels;$('#ruler').style.width=width+'px';$('#ruler').innerHTML=Array.from({length:Math.floor(total)+1},(_,i)=>'<span style="position:absolute;left:'+(i/total*100)+'%">'+i+'s</span>').join('');$('#scrubber').max=String(frames()-1);$('#durationCode').textContent=formatTime(total);$('#timelineZoomLabel').textContent=Math.round(S.timelineZoom*100)+'%';$$('[data-sceneclip]').forEach(e=>e.onclick=()=>select('scene',e.dataset.sceneclip));$$('[data-layerclip]').forEach(e=>{e.onclick=ev=>{ev.stopPropagation();select('layer',e.dataset.layerclip,{sceneId:e.dataset.scene})};e.onpointerdown=ev=>startLayerDrag(ev,e,width,total);e.onkeydown=ev=>{if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();nudgeLayer(e,ev.key==='ArrowRight'?1:-1)}}});$$('[data-audioclip]').forEach(e=>{e.onclick=ev=>{ev.stopPropagation();select('audio',e.dataset.audioclip)};e.onpointerdown=ev=>startAudioDrag(ev,e,width,total);e.onkeydown=ev=>{if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();nudgeAudio(e,ev.key==='ArrowRight'?1:-1)}}});$$('[data-phase]').forEach(e=>{e.onclick=ev=>{ev.stopPropagation();select('motion',undefined,{sceneId:e.dataset.scene,layerId:e.dataset.layer,motionIndex:Number(e.dataset.phase)})};e.onpointerdown=ev=>startPhaseDrag(ev,e,width,total);e.onkeydown=ev=>{if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();nudgePhase(e,ev.key==='ArrowRight'?1:-1)}}});updatePlayhead()}
const waveformCache=new Map;let waveformAudioContext;
async function waveformPeaks(src){if(waveformCache.has(src))return waveformCache.get(src);const promise=(async()=>{waveformAudioContext||=new AudioContext;const response=await fetch('/asset/'+src.split('/').map(encodeURIComponent).join('/'));if(!response.ok)throw new Error('Audio preview unavailable');const audio=await waveformAudioContext.decodeAudioData(await response.arrayBuffer()),channel=audio.getChannelData(0),count=512,peaks=new Float32Array(count),step=Math.max(1,Math.floor(channel.length/count));for(let index=0;index<count;index++){let peak=0;const end=Math.min(channel.length,(index+1)*step);for(let sample=index*step;sample<end;sample++)peak=Math.max(peak,Math.abs(channel[sample]));peaks[index]=peak}return peaks})();waveformCache.set(src,promise);try{return await promise}catch(error){waveformCache.delete(src);throw error}}
function drawWaveform(canvas,peaks){const rect=canvas.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2),width=Math.max(1,Math.round(rect.width*ratio)),height=Math.max(1,Math.round(rect.height*ratio));if(canvas.width!==width)canvas.width=width;if(canvas.height!==height)canvas.height=height;const context=canvas.getContext('2d');context.clearRect(0,0,width,height);context.strokeStyle='#86efac';context.lineWidth=Math.max(1,ratio);context.beginPath();const middle=height/2;for(let x=0;x<width;x++){const peak=peaks[Math.min(peaks.length-1,Math.floor(x/width*peaks.length))],amplitude=Math.max(1,peak*(height*.46));context.moveTo(x,middle-amplitude);context.lineTo(x,middle+amplitude)}context.stroke()}
function hydrateAudioWaveforms(){$$('[data-audioclip]').forEach(clip=>{if(clip.dataset.waveformReady)return;const track=S.project?.audio.find(item=>item.id===clip.dataset.audioclip);if(!track)return;clip.dataset.waveformReady='loading';const canvas=document.createElement('canvas');canvas.className='audio-waveform';canvas.setAttribute('aria-hidden','true');clip.prepend(canvas);waveformPeaks(track.src).then(peaks=>requestAnimationFrame(()=>{if(canvas.isConnected){drawWaveform(canvas,peaks);clip.dataset.waveformReady='true'}})).catch(()=>{canvas.remove();clip.dataset.waveformReady='unavailable'})})}
function nudgeLayer(element,direction){const scene=S.project.scenes.find(x=>x.id===element.dataset.scene),layer=scene?.layers.find(x=>x.id===element.dataset.layerclip);if(!scene||!layer)return;snapshot();const length=visibleDuration(layer,scene);layer.duration=length;layer.start=Math.max(0,Math.min(scene.duration-length,layer.start+direction/S.project.fps));select('layer',layer.id,{sceneId:scene.id});saveProject()}
function startLayerDrag(event,element,width,total){event.preventDefault();event.stopPropagation();const scene=S.project.scenes.find(x=>x.id===element.dataset.scene),layer=scene?.layers.find(x=>x.id===element.dataset.layerclip);if(!scene||!layer)return;snapshot();const length=visibleDuration(layer,scene);selectDuringTimelineDrag('layer',layer.id,{sceneId:scene.id});element.classList.add('active');S.drag={type:'layer-time',mode:event.target.dataset.layerHandle||'move',sceneId:scene.id,layerId:layer.id,startX:event.clientX,start:layer.start,duration:length,trimStart:layer.type==='video'?layer.trimStart:0,pixelsPerSecond:width/total,changed:false};$('#timeline').setPointerCapture(event.pointerId)}
function moveLayer(event){const d=S.drag,scene=S.project.scenes.find(x=>x.id===d.sceneId),layer=scene?.layers.find(x=>x.id===d.layerId);if(!scene||!layer)return;const frame=1/S.project.fps,delta=(event.clientX-d.startX)/d.pixelsPerSecond,candidates=timelineCandidates(scene,layer),offset=sceneOffset(scene);let guide;if(d.mode==='move'){const snapped=snapRange(d.start+delta,d.duration,candidates,d.pixelsPerSecond);layer.start=Math.max(0,Math.min(scene.duration-d.duration,snapped.value));layer.duration=d.duration;guide=snapped.guide}else if(d.mode==='left'){const end=d.start+d.duration,snapped=snapTime(d.start+delta,candidates,d.pixelsPerSecond),next=Math.max(0,Math.min(end-frame,snapped.value));layer.start=next;layer.duration=end-next;if(layer.type==='video')layer.trimStart=Math.max(0,d.trimStart+(next-d.start)*layer.playbackRate);guide=snapped.guide}else{const snapped=snapTime(d.start+d.duration+delta,candidates,d.pixelsPerSecond);layer.duration=Math.max(frame,Math.min(scene.duration-d.start,snapped.value-d.start));guide=snapped.guide}d.changed=true;const clip=$$('[data-layerclip]').find(item=>item.dataset.scene===scene.id&&item.dataset.layerclip===layer.id);if(clip){clip.style.left=(offset+layer.start)/duration()*100+'%';clip.style.width=layer.duration/duration()*100+'%'}showTimelineGuide(guide===undefined?undefined:offset+guide)}
function nudgeAudio(element,direction){const track=S.project.audio.find(item=>item.id===element.dataset.audioclip);if(!track)return;snapshot();track.start=Math.max(0,Math.min(duration()-1/S.project.fps,track.start+direction/S.project.fps));select('audio',track.id);saveProject()}
function startAudioDrag(event,element,width,total){event.preventDefault();event.stopPropagation();const track=S.project.audio.find(item=>item.id===element.dataset.audioclip);if(!track)return;snapshot();const length=track.duration||Math.max(1/S.project.fps,total-track.start);selectDuringTimelineDrag('audio',track.id);element.classList.add('active');S.drag={type:'audio-time',mode:event.target.dataset.audioHandle||'move',audioId:track.id,startX:event.clientX,start:track.start,duration:length,trimStart:track.trimStart,pixelsPerSecond:width/total,changed:false};$('#timeline').setPointerCapture(event.pointerId)}
function moveAudio(event){const d=S.drag,track=S.project.audio.find(item=>item.id===d.audioId);if(!track)return;const total=duration(),frame=1/S.project.fps,delta=(event.clientX-d.startX)/d.pixelsPerSecond,candidates=[0,total,S.frame/S.project.fps],others=S.project.audio.filter(item=>item!==track);others.forEach(item=>{candidates.push(item.start,item.start+(item.duration||Math.max(frame,total-item.start)))});let guide;if(d.mode==='move'){const snapped=snapRange(d.start+delta,d.duration,candidates,d.pixelsPerSecond);track.start=Math.max(0,Math.min(total-d.duration,snapped.value));track.duration=d.duration;guide=snapped.guide}else if(d.mode==='left'){const end=d.start+d.duration,snapped=snapTime(d.start+delta,candidates,d.pixelsPerSecond),next=Math.max(0,Math.min(end-frame,snapped.value));track.start=next;track.duration=end-next;track.trimStart=Math.max(0,d.trimStart+next-d.start);guide=snapped.guide}else{const snapped=snapTime(d.start+d.duration+delta,candidates,d.pixelsPerSecond);track.duration=Math.max(frame,Math.min(total-d.start,snapped.value-d.start));guide=snapped.guide}d.changed=true;const clip=$$('[data-audioclip]').find(item=>item.dataset.audioclip===track.id);if(clip){clip.style.left=track.start/total*100+'%';clip.style.width=track.duration/total*100+'%'}showTimelineGuide(guide)}
function trimLayerByFrame(element,edge,direction){const scene=S.project.scenes.find(item=>item.id===element?.dataset.scene),layer=scene?.layers.find(item=>item.id===element?.dataset.layerclip);if(!scene||!layer)return;snapshot();const frame=1/S.project.fps,length=visibleDuration(layer,scene);if(edge==='right')layer.duration=Math.max(frame,Math.min(scene.duration-layer.start,length+direction*frame));else{const end=layer.start+length,next=Math.max(0,Math.min(end-frame,layer.start+direction*frame));if(layer.type==='video')layer.trimStart=Math.max(0,layer.trimStart+(next-layer.start)*layer.playbackRate);layer.start=next;layer.duration=end-next}select('layer',layer.id,{sceneId:scene.id});saveProject()}
function trimAudioByFrame(element,edge,direction){const track=S.project.audio.find(item=>item.id===element?.dataset.audioclip);if(!track)return;snapshot();const frame=1/S.project.fps,total=duration(),length=track.duration||Math.max(frame,total-track.start);if(edge==='right')track.duration=Math.max(frame,Math.min(total-track.start,length+direction*frame));else{const end=track.start+length,next=Math.max(0,Math.min(end-frame,track.start+direction*frame));track.trimStart=Math.max(0,track.trimStart+next-track.start);track.start=next;track.duration=end-next}select('audio',track.id);saveProject()}
function trimPhaseByFrame(element,edge,direction){const scene=S.project.scenes.find(item=>item.id===element?.dataset.scene),layer=scene?.layers.find(item=>item.id===element?.dataset.layer),index=Number(element?.dataset.phase),motion=layer?.motion[index];if(!scene||!layer||!motion)return;snapshot();const frame=1/S.project.fps,available=visibleDuration(layer,scene);if(edge==='right')motion.duration=Math.max(frame,Math.min(available-motion.start,motion.duration+direction*frame));else{const end=motion.start+motion.duration,next=Math.max(0,Math.min(end-frame,motion.start+direction*frame));motion.start=next;motion.duration=end-next}select('motion',undefined,{sceneId:scene.id,layerId:layer.id,motionIndex:index});saveProject()}
