function easingEditor(label,key,ease){const kind=typeof ease==='string'?'named':ease?.type||'named',named=typeof ease==='string'?ease:'cubic-in-out';let details='';if(kind==='named')details=customSelect('Curve',key,named,namedEasings);else if(kind==='cubic-bezier')details='<div class="row">'+field('X1',key+'.x1',ease.x1,'number','min="0" max="1" step="0.01"')+field('Y1',key+'.y1',ease.y1,'number','step="0.01"')+field('X2',key+'.x2',ease.x2,'number','min="0" max="1" step="0.01"')+field('Y2',key+'.y2',ease.y2,'number','step="0.01"')+'</div>';else details='<div class="row">'+field('Mass',key+'.mass',ease.mass,'number','min="0.01" step="0.05"')+field('Stiffness',key+'.stiffness',ease.stiffness,'number','min="0.01" step="1"')+field('Damping',key+'.damping',ease.damping,'number','min="0.01" step="1"')+field('Velocity',key+'.velocity',ease.velocity,'number','step="0.05"')+'</div>';return'<div class="easing-card"><div class="field"><label>'+esc(label)+'</label><button class="select-button" data-ease-kind="'+esc(key)+'" data-ease-current="'+esc(kind)+'"><span>'+esc(kind==='named'?named:kind)+'</span>'+uiIcon('chevronDown')+'</button></div>'+easingCurve(ease,key)+details+'</div>'}
function changeEaseKind(key,kind){snapshot();const target=S.selected.kind==='layer'?selectedLayer():S.selected.kind==='scene'?S.project.scenes.find(scene=>scene.id===S.selected.id):null;if(!target)return;const value=kind==='cubic-bezier'?{type:'cubic-bezier',x1:.2,y1:.8,x2:.2,y2:1}:kind==='spring'?{type:'spring',mass:1,stiffness:170,damping:26,velocity:0}:'cubic-in-out';setValueAt(target,key,value);saveProject();renderInspector()}
function snapshot(){S.undo.push(JSON.stringify({project:S.project,studio:S.studio}));if(S.undo.length>50)S.undo.shift();S.redo=[]}
function selectedLayer(){return S.project.scenes.find(x=>x.id===S.selected.sceneId)?.layers.find(x=>x.id===(S.selected.kind==='motion'?S.selected.layerId:S.selected.id))}
