function selectedMotion(){const scene=S.project.scenes.find(x=>x.id===S.selected.sceneId),layer=scene?.layers.find(x=>x.id===S.selected.layerId),motion=layer?.motion[S.selected.motionIndex];return scene&&layer&&motion?{scene,layer,motion}:null}
