function addKeyframe(property){const layer=selectedLayer();if(!layer)return;if(motionOwns(layer,property)){toast('A named motion already owns '+property+'. Tune its directive or remove it first.','bad');return}snapshot();const current=layer.transform[property];const end=Math.max(.1,layer.duration||1);if(typeof current==='number')layer.transform[property]={keyframes:[{at:0,value:current,ease:'linear'},{at:end,value:current,ease:'cubic-in-out'}]};else{const last=current.keyframes.at(-1)||{at:0,value:0,ease:'linear'};current.keyframes.push({at:last.at+.25,value:last.value,ease:'cubic-in-out'})}saveProject();renderInspector()}
