async function cancelExport(id){try{const updated=await api('/api/jobs/'+encodeURIComponent(id)+'/cancel',{method:'POST'});S.jobs=S.jobs.map(item=>item.id===id?updated:item);renderExportProgress();toast('Export cancelled')}catch(error){toast(error.message,'bad','render-cancel-error')}}
function renderExportProgress(){const area=$('#renderProgress'),button=$('#startRender');if(!area)return;const job=S.jobs.find(item=>item.id===S.activeRenderId),size=job?.width&&job?.height?' · '+job.width+'×'+job.height:'';if(!job){area.innerHTML='';wireExportButtons();return}if(job.status==='queued'){if(button){button.disabled=true;button.textContent='Queued'}area.innerHTML='<div class="notice">Waiting for the renderer'+size+'.</div><button class="ghost danger" style="width:100%;margin-top:8px" data-cancel-export="'+job.id+'">Cancel export</button>';wireExportButtons()}else if(job.status==='rendering'){if(button){button.disabled=true;button.textContent='Rendering '+Math.round(job.progress*100)+'%'}area.innerHTML='<div class="notice">Rendering '+Math.round(job.progress*100)+'%'+size+'</div><button class="ghost danger" style="width:100%;margin-top:8px" data-cancel-export="'+job.id+'">Cancel export</button>';wireExportButtons()}else if(job.status==='failed'){if(button){button.disabled=false;button.textContent='Try again'}area.innerHTML='<div class="notice error">'+esc(job.error||'Export failed')+'</div>'}else if(job.status==='cancelled'){if(button){button.disabled=false;button.textContent='Start render'}area.innerHTML='<div class="notice">Export cancelled. No partial file was kept.</div>'}else if(job.status==='complete'){if(button){button.disabled=false;button.textContent='Export again'}area.innerHTML='<div class="notice">Export complete'+size+'<br><strong>'+esc(job.output)+'</strong></div><button class="ghost" style="width:100%" data-download-export="'+esc(job.output.split('/').pop())+'">Download</button>';wireExportButtons()}}
